# 91_equivalence_figure.R: supplementary model-equivalence figure from 90_equivalence.R tables (plotting only). Run from final/.
suppressPackageStartupMessages({library(ggplot2); library(dplyr); library(patchwork); library(scales)}); stopifnot(requireNamespace("svglite", quietly = TRUE))
IN <- "revision_random/tables"; OUTF <- "revision_random/figures"; Cf <- read.csv(file.path(IN, "eq_coefficients.csv")); Cu <- read.csv(file.path(IN, "eq_fitted_curves.csv")); Sm <- read.csv(file.path(IN, "eq_validation_table.csv"))
ink <- "#252B2D"; petrol <- "#246878"; orange <- "#C45C19"; grey <- "#848B8D"; grid_col <- "#E5E9E9"; TXC <- c(BM = petrol, ZP = orange); TXL <- c(BM = "Macroinvertebrates", ZP = "Zooplankton")
lab <- function(cmp, k) { ref <- sub(" .*", "", sub("^E[0-9]n? [a-z-]+ MS-GDUM k=[0-9]+ (native fit )?vs ", "", cmp)); paste0(c(E1 = "E1 additive vs gdmmTMB", E2 = "E2 spread-only vs gdm", E3 = "E3 spread-only vs zetadiv", E2n = "E2n native vs gdm", E3n = "E3n native vs zetadiv")[sub(" .*", "", cmp)], if (k > 2 || grepl("^E3", cmp)) paste0(", k = ", k) else ", k = 2") }
Cf <- Cf |> mutate(lab = mapply(lab, comparison, order)); Cu <- Cu |> mutate(lab = mapply(lab, comparison, order))
base <- theme_minimal(base_size = 8.5, base_family = "sans") + theme(text = element_text(colour = ink), axis.text = element_text(size = 6.8, colour = ink), axis.title = element_text(size = 8, colour = ink), axis.line = element_line(colour = ink, linewidth = .3), axis.ticks = element_line(colour = ink, linewidth = .25),
  axis.ticks.length = unit(1, "mm"), panel.grid.major = element_line(colour = grid_col, linewidth = .25), panel.grid.minor = element_blank(), panel.spacing = unit(2.5, "mm"), strip.background = element_blank(), strip.text = element_text(size = 6.8, face = "bold", colour = ink), legend.position = "bottom", legend.title = element_blank(),
  legend.text = element_text(size = 7), legend.margin = margin(0, 0, 0, 0), legend.box.spacing = unit(1, "mm"), plot.tag = element_text(size = 11, face = "bold"), plot.margin = margin(2, 3, 1, 2))
CLS <- c(intercept = 15, spline = 16, distance = 17, position = 18); idplot <- function(d, tag) { lim <- range(c(d$reference, d$zetaGDUM)); ggplot(d, aes(reference, zetaGDUM, colour = taxon, shape = term_class)) + geom_abline(slope = 1, intercept = 0, colour = grey, linewidth = .35) + geom_point(size = 1.6, alpha = .85) + facet_wrap(~lab, nrow = 1, scales = "free", labeller = labeller(lab = label_wrap_gen(20))) +
    scale_colour_manual(values = TXC, labels = TXL) + scale_shape_manual(values = CLS) + labs(tag = tag, x = "Reference coefficient", y = "zetaGDUM coefficient") + base }
A <- idplot(Cf |> filter(matched_link_and_criterion), "A"); B <- idplot(Cf |> filter(!matched_link_and_criterion), "B") + theme(panel.background = element_rect(fill = "#F6F7F7", colour = NA), legend.position = "none")
cur <- function(d, tag, matched) { ggplot(d, aes(x_log10)) + geom_line(aes(y = f_reference, colour = taxon, group = taxon), linewidth = 1.1, alpha = .35) + geom_line(aes(y = f_zetaGDUM, colour = taxon, group = taxon), linewidth = .55, linetype = "42") + facet_grid(lab ~ predictor, scales = "free", labeller = labeller(lab = label_wrap_gen(22))) + scale_colour_manual(values = TXC, labels = TXL) +
    labs(tag = tag, x = expression(log[10] ~ "predictor value"), y = "Fitted f(x)") + base + theme(strip.text.y = element_text(angle = 0, hjust = 0, size = 6)) }
Cm <- cur(Cu |> filter(matched_link_and_criterion, order %in% c(2, 3, 5)), "C", TRUE) + theme(legend.position = "none"); Cn <- cur(Cu |> filter(!matched_link_and_criterion, order %in% c(2, 3, 5)), "D", FALSE) + theme(panel.background = element_rect(fill = "#F6F7F7", colour = NA), legend.position = "none")
fig <- (A / B / Cm / Cn) + plot_layout(heights = c(1, 1, 2.1, 1.7))
for (ext in c("pdf", "svg", "png")) ggsave(file.path(OUTF, paste0("FigureS_model_equivalence.", ext)), fig, width = 183, height = 245, units = "mm", dpi = 600, bg = "white", device = switch(ext, pdf = grDevices::cairo_pdf, svg = svglite::svglite, png = "png"))
write.csv(Cf, file.path(OUTF, "FigureS_model_equivalence_AB_coefficients.csv"), row.names = FALSE); write.csv(Cu, file.path(OUTF, "FigureS_model_equivalence_CD_curves.csv"), row.names = FALSE)
# Caption notes: A matched link/criterion (E1 same logit likelihood; E2 negative-exponential link with gdm deviance; E3 binomial(log) zetadiv likelihood); B UNMATCHED native zetaGDUM fits (logit link, own I-spline basis, dissimilarity response): shown to document the differences, no equivalence claimed.
# C, D fitted transformations f(x) = sum_j beta_j I_j(x) on the predictor's own scale for the reference and zetaGDUM fits (D: unmatched).
